{"status":"edit","missing_fact":"","edits":[{"path":"logic.hpp","hash":"57ae0de601465c005108b6b3baa934a11d0aa434dd2e6d6d59f9d876612fa68b","old":"inline int parse_port(std::string text) { return text.empty() ? -1 : std::atoi(text.c_str()); }","new":"inline int parse_port(std::string text) {
    if (text.empty()) return -1;
    int port = 0;
    for (unsigned char c : text) {
        if (c < '0' || c > '9') return -1;
        int digit = c - '0';
        if (port > (65535 - digit) / 10) return -1;
        port = port * 10 + digit;
    }
    return port == 0 ? -1 : port;
}"}]}
